{"files":[{"path":"src/test/java/com/example/shortener/service/LinkServiceTest.java","content":"package com.example.shortener.service;

import com.example.shortener.api.LinkResponse;
import com.example.shortener.domain.Link;
import com.example.shortener.exception.CodeGenerationException;
import com.example.shortener.exception.LinkNotFoundException;
import com.example.shortener.repository.LinkRepository;
import jakarta.servlet.http.HttpServletRequest;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.dao.DataIntegrityViolationException;

import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class LinkServiceTest {
    @Mock LinkRepository links;
    @Mock AuditService audit;
    @Mock UrlValidator validator;
    @Mock ShortCodeGenerator generator;
    @Mock ShortUrlBuilder builder;
    @Mock HttpServletRequest request;
    @InjectMocks LinkService service;

    @Test
    void retriesCollisionThenCreatesAndAudits() {
        when(generator.generate()).thenReturn("AAAAAAA", "BBBBBBB");
        Link saved = new Link("BBBBBBB", "https://example.com", java.time.Instant.now());
        when(links.saveAndFlush(any(Link.class))).thenThrow(new DataIntegrityViolationException("collision")).thenReturn(saved);
        when(request.getRemoteAddr()).thenReturn("192.0.2.1");
        when(builder.build("BBBBBBB", request)).thenReturn("http://localhost/BBBBBBB");

        LinkResponse response = service.create("https://example.com", request);

        assertThat(response.code()).isEqualTo("BBBBBBB");
        verify(validator).validate("https://example.com");
        verify(audit).record("LINK_CREATED", "BBBBBBB", "192.0.2.1", "SUCCESS");
    }

    @Test
    void rejectsExhaustedCollisions() {
        when(generator.generate()).thenReturn("AAAAAAA");
        when(links.saveAndFlush(any(Link.class))).thenThrow(new DataIntegrityViolationException("collision"));
        assertThatThrownBy(() -> service.create("https://example.com", request))
                .isInstanceOf(CodeGenerationException.class)
                .hasMessage("Unable to create a short link");
        verify(audit, never()).record(any(), any(), any(), any());
        verify(links, times(10)).saveAndFlush(any(Link.class));
    }

    @Test
    void detailsAndResolveCoverSuccessAndMissingBranches() {
        Link link = new Link("Ab3xYz9", "https://example.com/a", java.time.Instant.now());
        when(links.findByCode("Ab3xYz9")).thenReturn(Optional.of(link));
        when(builder.build("Ab3xYz9", request)).thenReturn("http://localhost/Ab3xYz9");
        when(request.getRemoteAddr()).thenReturn("198.51.100.5");
        assertThat(service.details("Ab3xYz9", request).originalUrl()).isEqualTo("https://example.com/a");
        when(links.incrementClickCount("Ab3xYz9")).thenReturn(1);
        assertThat(service.resolve("Ab3xYz9", request)).isEqualTo("https://example.com/a");
        verify(audit).record("REDIRECTED", "Ab3xYz9", "198.51.100.5", "REDIRECTED");

        when(links.findByCode("missing")).thenReturn(Optional.empty());
        assertThatThrownBy(() -> service.details("missing", request)).isInstanceOf(LinkNotFoundException.class);
        when(links.incrementClickCount("missing")).thenReturn(0);
        assertThatThrownBy(() -> service.resolve("missing", request)).isInstanceOf(LinkNotFoundException.class);
        verify(audit, times(2)).record(eq("UNKNOWN_CODE"), eq("missing"), any(), eq("NOT_FOUND"));
    }

    @Test
    void resolveHandlesIncrementThenLookupRaceAsMissing() {
        when(links.incrementClickCount("race")).thenReturn(1);
        when(links.findByCode("race")).thenReturn(Optional.empty());
        assertThatThrownBy(() -> service.resolve("race", request)).isInstanceOf(LinkNotFoundException.class);
        verify(audit).record(eq("UNKNOWN_CODE"), eq("race"), any(), eq("NOT_FOUND"));
    }

    @Test
    void rejectsInvalidCodeBeforeRepositoryAccess() {
        assertThatThrownBy(() -> service.validateCode("too-short"))
                .isInstanceOf(LinkNotFoundException.class);
        verifyNoInteractions(links, audit);
    }
}
"},{"path":"src/test/java/com/example/shortener/service/UrlValidatorTest.java","content":"package com.example.shortener.service;

import com.example.shortener.exception.InvalidUrlException;
import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class UrlValidatorTest {
    private final UrlValidator validator = new UrlValidator();

    @Test
    void acceptsAbsoluteHttpAndHttpsUrls() {
        assertThatCode(() -> validator.validate("http://example.com/path?q=1#part")).doesNotThrowAnyException();
        assertThatCode(() -> validator.validate("HTTPS://example.com:8443/path")).doesNotThrowAnyException();
    }

    @Test
    void rejectsNullBlankRelativeUnsupportedMalformedAndOverlongUrls() {
        for (String value : new String[]{null, "", "   ", "/relative", "ftp://example.com", "http:///path", "http://", "http://exa mple.com"}) {
            assertThatThrownBy(() -> validator.validate(value))
                    .isInstanceOf(InvalidUrlException.class)
                    .hasMessage("url must be an absolute HTTP or HTTPS URL");
        }

        String overlong = "https://example.com/" + "x".repeat(2030);
        assertThat(overlong).hasSizeGreaterThan(2048);
        assertThatThrownBy(() -> validator.validate(overlong))
                .isInstanceOf(InvalidUrlException.class)
                .hasMessage("url must be an absolute HTTP or HTTPS URL");
    }
}
